"""Hack-vN core: CPU + address decode + read-data mux, with the RAM *outside* the netlist (generated by
the builder program).  Inputs: romdata[8] (ROM part DATA pins), ramrd[8] (RAM read data), run.
Outputs: rom_addr[12], arm_addr[4], arm_en, wdata[8], ram_addr[abits], ram_we (write strobe for RAM)."""
from nandgen import *
from nl_hackvn import hackvn_core


def build_core(level=2, ram_abits=7, rom_abits=12):
    n = Net(level)
    romdata = n.bus_in('romdata', 8)
    ramrd = n.bus_in('ramrd', 8)
    run = n.input('run')
    reset = n._raw(run, run)           # run feeds exactly one gate (both pins): released by the last wire
    box = {}

    def get_rdata(addr):
        with n.scope('decode'):
            hiz = ONE
            for b in addr[ram_abits:13]:
                hiz = n.and_(hiz, n.not_(b))
            box['ram_sel'] = hiz
            arm = n.not_(addr[12])
            for b in addr[4:12]:
                arm = n.and_(arm, b)
            box['arm_sel'] = arm
            return [n.nand(n.nand(hiz, ramrd[j]), n.nand(addr[12], romdata[j])) for j in range(8)]

    s = hackvn_core(n, reset, get_rdata)
    addr, we = s['addr'], s['we']
    with n.scope('decode'):
        we_ram = n.and_(we, box['ram_sel'])
        arm_en = n.and_(we, box['arm_sel'])
    outs = {'rom_addr': addr[:rom_abits], 'arm_addr': addr[:4], 'arm_en': [arm_en], 'wdata': s['wdata'],
            'ram_addr': addr[:ram_abits], 'ram_we': [we_ram],
            'addr': addr, 'we': [we], 'pc': s['pc'], 'a': s['a'], 'd': s['d'], 'st': s['st'], 'ir': s['ir']}
    return n.finalize(outs)


if __name__ == '__main__':
    import nandgen as ng
    for ab in (5, 6, 7, 8, 10):
        c = build_core(2, ab)
        raw, z, x = ng.sizes(c)
        print(f'ram_abits {ab}: NAND {len(c.gates)} DFF {c.n_dff} inputs {c.n_in} xz {x}')
